// Original, redistributable two-operator sustained FM tone; no game assets.
extern crate alloc;

pub const OPL_TONE: [(u16, u8); 12] = [
    (0x20, 0x21), (0x23, 0x21), (0x40, 0x10), (0x43, 0),
    (0x60, 0xF0), (0x63, 0xF0), (0x80, 0x07), (0x83, 0x07),
    (0xE0, 0), (0xC0, 0x30), (0xA0, 0x98), (0xB0, 0x31),
];

pub fn opl3_tone_program() -> alloc::vec::Vec<u8> {
    let mut code = alloc::vec![0xB0, 0xFF, 0xE6, 0x21]; // Mask IRQs.
    for register in [0x30, 0x31, 0x34, 0x35] {
        code.extend_from_slice(&[0xBA, 0x24, 2, 0xB0, register, 0xEE, 0x42, 0xB0, 0xF8, 0xEE]);
    }
    for (register, value) in OPL_TONE {
        code.extend_from_slice(&[0xBA, 0x88, 3, 0xB0, register as u8, 0xEE, 0x42, 0xB0, value, 0xEE]);
    }
    code.extend_from_slice(&[0xEB, 0xFE]);
    code
}
